// Updated Prepare Safe Chapter Storage Node
// Handles both "Chapter X" and "#N:" formats for content splitting

const manuscriptText = $("Retrieve Manuscript").first().json.full_text;
const manuscriptId = $("Retrieve Manuscript").first().json.id;
const hasPrologue =
  $("Webhook").first().json.body?.hasPrologue === "true" ||
  $("Webhook").first().json.body?.hasPrologue === true;
const hasEpilogue =
  $("Webhook").first().json.body?.hasEpilogue === "true" ||
  $("Webhook").first().json.body?.hasEpilogue === true;

console.log(
  `Processing manuscript with Prologue: ${hasPrologue}, Epilogue: ${hasEpilogue}`,
);

if (!manuscriptText || manuscriptText.length < 100) {
  throw new Error("No manuscript text available for chapter extraction");
}

// Helper function to normalize content spacing while preserving paragraphs
function normalizeContent(content) {
  const lines = content.split("\n").slice(1); // Remove first line (chapter header)

  const processedLines = [];

  for (let i = 0; i < lines.length; i++) {
    const currentLine = lines[i].trim();
    const nextLine = lines[i + 1]?.trim() || "";

    // Skip empty lines
    if (!currentLine) {
      // Empty line = paragraph break
      processedLines.push("\n\n");
      continue;
    }

    // Check if this line ends a paragraph
    const endsWithPunctuation = /[.!?"]$/.test(currentLine);
    const nextStartsWithCapital = /^[A-Z"]/.test(nextLine);
    const nextIsEmpty = !nextLine;

    if (endsWithPunctuation && (nextStartsWithCapital || nextIsEmpty)) {
      // End of paragraph
      processedLines.push(currentLine + "\n\n");
    } else if (!nextLine) {
      // Last line
      processedLines.push(currentLine);
    } else {
      // Mid-paragraph line break - convert to space
      processedLines.push(currentLine + " ");
    }
  }

  return processedLines
    .join("")
    .replace(/ {2,}/g, " ") // Collapse multiple spaces
    .replace(/\s+([.,!?;:])/g, "$1") // Remove space before punctuation
    .replace(/\n{3,}/g, "\n\n") // Collapse multiple paragraph breaks
    .trim();
}

// Detect which format this manuscript uses
const hasStandardChapters = /CHAPTER\s+\d+|Chapter\s+\d+/i.test(manuscriptText);
const hasHashtagChapters = /^#\d+(?:\s*[,&\d\s]*)(?::\s*|\s+)/m.test(
  manuscriptText,
);

console.log(
  `Format detection - Standard chapters: ${hasStandardChapters}, Hashtag chapters: ${hasHashtagChapters}`,
);

// SMART CHAPTER SPLITTING - handle both formats
let chapterPattern;
if (hasHashtagChapters && !hasStandardChapters) {
  // Hashtag format: #1: Title, #2: Title, etc.
  // Also include Introduction as a potential section
  chapterPattern =
    /(?=(?:^#\d+(?:\s*[,&\d\s]*)(?::\s*|\s+)|^PROLOGUE|^Prologue|^EPILOGUE|^Epilogue|^Introduction\s*$))/im;
} else {
  // Standard format (existing behavior)
  chapterPattern =
    /(?=(?:PROLOGUE|Prologue|CHAPTER\s+\d+|Chapter\s+\d+|EPILOGUE|Epilogue))/i;
}

const rawSplits = manuscriptText
  .split(chapterPattern)
  .filter((section) => section.trim().length > 100);

console.log(`Raw splits found: ${rawSplits.length} sections`);

// Identify what each split is
const identifiedSections = rawSplits.map((section) => {
  const firstLine = section.trim().substring(0, 200).split("\n")[0];

  if (/^PROLOGUE|^Prologue/i.test(firstLine)) {
    return { type: "prologue", content: section.trim() };
  } else if (/^EPILOGUE|^Epilogue/i.test(firstLine)) {
    return { type: "epilogue", content: section.trim() };
  } else if (/^Introduction\s*$/i.test(firstLine)) {
    // Treat Introduction as prologue-like (chapter 0) if no explicit prologue
    return { type: "introduction", content: section.trim() };
  } else if (/^CHAPTER\s+(\d+)|^Chapter\s+(\d+)/i.test(firstLine)) {
    // Standard chapter format
    const match = firstLine.match(/CHAPTER\s+(\d+)|Chapter\s+(\d+)/i);
    const num = parseInt(match[1] || match[2]);
    return { type: "chapter", number: num, content: section.trim() };
  } else if (/^#(\d+)/.test(firstLine)) {
    // Hashtag chapter format - extract first number
    const match = firstLine.match(/^#(\d+)/);
    const num = parseInt(match[1]);
    return { type: "chapter", number: num, content: section.trim() };
  } else {
    return { type: "unknown", content: section.trim() };
  }
});

console.log(
  "Identified sections:",
  identifiedSections
    .map((s) => `${s.type}${s.number ? " " + s.number : ""}`)
    .join(", "),
);

// Extract chapter titles from the first line of each section
const extractTitle = (content, chapterNumber, isHashtagFormat) => {
  const firstLine = content.split("\n")[0].trim();

  if (isHashtagFormat) {
    // Hashtag format: "#1: Fatigue" or "#4 5 & 6: Weight Gain..."
    const hashtagTitle = firstLine.match(
      /^#\d+(?:\s*[,&\d\s]*)(?::\s*|\s+)(.+)$/i,
    );
    if (hashtagTitle) {
      return hashtagTitle[1].trim();
    }
  }

  // Standard format: "Chapter X - Title"
  const titleWithHyphen = firstLine.match(/Chapter\s+\d+\s*-\s*(.+)$/i);
  if (titleWithHyphen) {
    return titleWithHyphen[1].trim();
  }

  const titleWithoutHyphen = firstLine.match(/Chapter\s+\d+\s+(.+)$/i);
  if (titleWithoutHyphen) {
    return titleWithoutHyphen[1].trim();
  }

  return `Chapter ${chapterNumber}`;
};

// Build final chapters array
const finalChapters = [];
const isHashtagFormat = hasHashtagChapters && !hasStandardChapters;

// Add Prologue (chapter 0) if it exists
const prologueSection = identifiedSections.find((s) => s.type === "prologue");
if (hasPrologue && prologueSection) {
  finalChapters.push({
    number: 0,
    title: "Prologue",
    content: normalizeContent(prologueSection.content),
  });
  console.log("Added Prologue as chapter 0");
}

// Add Introduction as chapter 0 if no prologue but has introduction
const introSection = identifiedSections.find((s) => s.type === "introduction");
if (!hasPrologue && introSection) {
  finalChapters.push({
    number: 0,
    title: "Introduction",
    content: normalizeContent(introSection.content),
  });
  console.log("Added Introduction as chapter 0");
}

// Add numbered chapters - deduplicate by keeping the longest content for each number
const chapterSections = identifiedSections.filter((s) => s.type === "chapter");

// Group by chapter number and keep the longest content
const chapterMap = new Map();
chapterSections.forEach((section) => {
  const existing = chapterMap.get(section.number);
  if (!existing || section.content.length > existing.content.length) {
    chapterMap.set(section.number, section);
  }
});

// Convert map back to sorted array
const uniqueChapterSections = Array.from(chapterMap.values()).sort(
  (a, b) => a.number - b.number,
);

console.log(
  `Found ${chapterSections.length} chapter sections, deduplicated to ${uniqueChapterSections.length} unique chapters`,
);

uniqueChapterSections.forEach((section) => {
  const title = extractTitle(section.content, section.number, isHashtagFormat);

  finalChapters.push({
    number: section.number,
    title: title,
    content: normalizeContent(section.content),
  });
});

console.log(`Added ${uniqueChapterSections.length} numbered chapters`);

// Add Epilogue (chapter 999) if it exists
const epilogueSection = identifiedSections.find((s) => s.type === "epilogue");
if (hasEpilogue && epilogueSection) {
  finalChapters.push({
    number: 999,
    title: "Epilogue",
    content: normalizeContent(epilogueSection.content),
  });
  console.log("Added Epilogue as chapter 999");
}

// Sanitize titles (escape quotes, limit length)
const sanitizedChapters = finalChapters.map((ch) => ({
  number: ch.number,
  title: ch.title.replace(/'/g, "''").substring(0, 255),
  content: ch.content,
}));

console.log(
  `✅ Final: ${sanitizedChapters.length} chapters prepared for storage`,
);

return {
  json: {
    manuscriptId: manuscriptId,
    chapters: sanitizedChapters,
    totalChapters: sanitizedChapters.length,
    format: isHashtagFormat ? "hashtag" : "standard",
  },
};

console.log('Total chapters received:', $json.chapters ? $json.chapters.length : 'undefined');
console.log('Chapter data:', JSON.stringify($json.chapters, null, 2));

return { json: $json };

// Updated Parse Chapters Node
// Handles both "Chapter X - Title" and "#N: Title" formats

const manuscriptText = $("Retrieve Manuscript").first().json.full_text;
const expectedChapters =
  parseInt($("Webhook").first().json.body.expectedChapters) || 0;

// Extract chapter titles using multiple regex patterns

// Pattern 1: Standard "Chapter X - Title" or "Chapter X Title" format
const standardPattern = /^Chapter\s+(\d+)\s*[-:]?\s*(.*)$/gim;

// Pattern 2: Hashtag format "#N: Title" or "#N Title"
// Takes first number only (handles "#4 5 & 6: Title" as chapter 4)
const hashtagPattern = /^#(\d+)(?:\s*[,&\d\s]*)(?::\s*|\s+)(.+)$/gim;

const standardMatches = [...manuscriptText.matchAll(standardPattern)];
const hashtagMatches = [...manuscriptText.matchAll(hashtagPattern)];

console.log(`Standard format matches: ${standardMatches.length}`);
console.log(`Hashtag format matches: ${hashtagMatches.length}`);

// Combine all matches
const allMatches = [
  ...standardMatches.map((match) => ({
    number: parseInt(match[1]),
    title: match[2]?.trim() || `Chapter ${match[1]}`,
  })),
  ...hashtagMatches.map((match) => ({
    number: parseInt(match[1]),
    title: match[2]?.trim() || `Section ${match[1]}`,
  })),
];

// Remove duplicates by number (keep first occurrence)
const uniqueChapters = [];
const seenNumbers = new Set();

for (const chapter of allMatches) {
  if (!seenNumbers.has(chapter.number)) {
    uniqueChapters.push(chapter);
    seenNumbers.add(chapter.number);
  }
}

// Sort by chapter number
uniqueChapters.sort((a, b) => a.number - b.number);

console.log(`Found ${uniqueChapters.length} unique chapters`);
if (uniqueChapters.length > 0) {
  console.log(
    "First 5 chapters:",
    uniqueChapters
      .slice(0, 5)
      .map((c) => `${c.number}: ${c.title}`)
      .join(", "),
  );
}

return {
  json: {
    success: true,
    chapters: uniqueChapters,
    totalChapters: uniqueChapters.length,
    format:
      hashtagMatches.length > standardMatches.length ? "hashtag" : "standard",
  },
};
